import json
from itertools import combinations

names = ["Garza","Yates","Zimmer","Flores","Lynch","King","Meyer","Ortiz"]
cls   = [1,3,3,1,2,2,2,2]
start = (0,0,0,1,1,2,2,2)  # 0=RealProp, 1=Southco, 2=Trustcorp
idx = {n:i for i,n in enumerate(names)}

def moves(s):
    n = len(s)
    for a in range(n):
        for b in range(a+1, n):
            if s[a] != s[b] and cls[a] == cls[b]:
                t = list(s); t[a], t[b] = t[b], t[a]
                yield tuple(t)
    for a in range(n):
        for c in (1, 2):
            if cls[a] != c:
                continue
            small = c + 1
            for X in range(3):
                if s[a] != X:
                    continue
                for Y in range(3):
                    if Y == X:
                        continue
                    for b, d in combinations(range(n), 2):
                        if cls[b] == small and cls[d] == small and s[b] == Y and s[d] == Y:
                            t = list(s)
                            t[a] = Y; t[b] = X; t[d] = X
                            yield tuple(t)

seen = {start}
stack = [start]
while stack:
    s = stack.pop()
    for t in moves(s):
        if t not in seen:
            seen.add(t)
            stack.append(t)

def owned(s, comp):
    return {names[i] for i in range(8) if s[i] == comp}

conds = {
    "A": lambda s: owned(s,0) == {"Lynch","Meyer","Ortiz"},
    "B": lambda s: owned(s,1) == {"Garza","Meyer"},
    "C": lambda s: owned(s,1) == {"King","Meyer","Ortiz"},
    "D": lambda s: owned(s,2) == {"Flores","Yates"},
    "E": lambda s: owned(s,2) == {"Garza","Lynch"},
}
res = {k: any(f(s) for s in seen) for k, f in conds.items()}
impossible = [k for k, v in res.items() if not v]
if len(impossible) == 1:
    ans = impossible[0]
else:
    ans = "UNSUPPORTED"
print(json.dumps({"final_answer": ans,
                  "evidence": {"reachable_states": len(seen), "possible": res}}))
